{
  "is_event": true,
  "summary": "智元机器人第2万台具身智能机器人交付长隆，标志具身智能在文旅场景实现规模化商业落地，验证行业从研发向量产应用跨越。",
  "impact_chain": [
    "具身智能机器人规模化交付→验证商业化闭环能力→利好核心零部件供应链（减速器、伺服电机、传感器）",
    "文旅场景常态化运行→拓展服务机器人应用边界→利好服务机器人集成商及文旅智能化解决方案提供商",
    "头部企业量产进度加速→行业竞争加剧但市场空间打开→利好具备技术壁垒的整机厂商及AI算法提供商"
  ],
  "sectors": [
    "机器人",
    "人工智能",
    "旅游酒店"
  ],
  "candidates": [
    {
      "name": "三花智控",
      "sector": "机器人",
      "logic": "全球领先的执行器组件供应商，为人形机器人提供机电执行关键部件，受益于行业量产放量",
      "direction": "利好"
    },
    {
      "name": "绿的谐波",
      "sector": "机器人",
      "logic": "精密减速器龙头，人形机器人关节核心部件供应商，直接受益于具身智能机器人产量提升",
      "direction": "利好"
    },
    {
      "name": "柯力传感",
      "sector": "机器人",
      "logic": "国内应变式传感器龙头，积极布局人形机器人六维力/力矩传感器，契合具身智能感知需求",
      "direction": "利好"
    },
    {
      "name": "长隆集团",
      "sector": "旅游酒店",
      "logic": "事件直接受益方，通过引入具身智能机器人提升游客体验及运营效率，打造智慧文旅标杆",
      "direction": "利好"
    }
  ]
}

{
  "is_event": true,
  "summary": "碳酸锂期货主力合约大跌3.05%且持仓增加，显示空头力量增强及供需宽松预期强化，利空锂矿及正极材料板块。",
  "impact_chain": [
    "期货价格下跌+增仓下行→市场看空情绪升温→锂盐厂挺价难度加大→上游锂资源企业盈利预期下调",
    "原材料成本下降预期→中游电池及正极材料厂商成本压力缓解→短期利好中下游制造环节毛利修复"
  ],
  "sectors": [
    "锂矿",
    "锂电池",
    "有色金属"
  ],
  "candidates": [
    {
      "name": "赣锋锂业",
      "sector": "锂矿",
      "logic": "全球锂生态龙头，拥有大量锂资源储备，锂价下跌直接压缩其销售毛利及存货价值。",
      "direction": "利空"
    },
    {
      "name": "天齐锂业",
      "sector": "锂矿",
      "logic": "主要收入来源为锂精矿及锂化合物销售，对锂价波动高度敏感，价格下行严重冲击业绩。",
      "direction": "利空"
    },
    {
      "name": "宁德时代",
      "sector": "锂电池",
      "logic": "作为下游电池龙头，碳酸锂价格下跌有助于降低原材料采购成本，改善毛利率。",
      "direction": "利好"
    },
    {
      "name": "亿纬锂能",
      "sector": "锂电池",
      "logic": "二线电池厂商，同样受益于上游原材料成本下行，提升产品竞争力及盈利空间。",
      "direction": "利好"
    }
  ]
}

